INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900001, 'business', '2.0-cineastra', 'CineAstra', CAST('{"legalName":"CineAstra Entretenimento Ltda.","cnpj":"48273000001082","physicalAddress":"Avenida Paulista, 1578, Bela Vista, São Paulo - SP","email":"contato@cineastra.com.br","supportChannels":["Central de atendimento pelo site","contato@cineastra.com.br"]}' AS JSON), 'https://cineastra.com.br/business', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900002, 'team', '2.0-cineastra', 'Nossa equipe', CAST('{"text":"Pessoas dedicadas a criar uma experiência acolhedora em cada sessão."}' AS JSON), 'https://cineastra.com.br/team', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900003, 'history', '2.0-cineastra', 'Nossa história', CAST('{"text":"A CineAstra reúne cinema, tecnologia e atendimento em uma experiência integrada."}' AS JSON), 'https://cineastra.com.br/history', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900004, 'reputation', '2.0-cineastra', 'Compromisso com o público', CAST('{"text":"Qualidade de imagem, conforto, acessibilidade e respeito ao público orientam nossas unidades."}' AS JSON), 'https://cineastra.com.br/reputation', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900005, 'partners', '2.0-cineastra', 'Nossos parceiros', CAST('{"text":"Trabalhamos com fornecedores especializados em alimentos e soluções audiovisuais."}' AS JSON), 'https://cineastra.com.br/partners', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900006, 'social-campaigns', '2.0-cineastra', 'Cinema para todos', CAST('{"text":"Promovemos sessões acessíveis e iniciativas culturais nas comunidades de nossas unidades."}' AS JSON), 'https://cineastra.com.br/social-campaigns', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900007, 'terms', '2.0-cineastra', 'Termos de Uso', CAST('{"text":"Confira os itens, valores, horários e condições da compra antes de confirmar o pagamento. Os ingressos são pessoais e devem ser exibidos no acesso à sala."}' AS JSON), 'https://cineastra.com.br/terms', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900008, 'privacy', '2.0-cineastra', 'Política de Privacidade', CAST('{"text":"Os dados da conta são utilizados para autenticação, atendimento, processamento de pedidos e disponibilização dos serviços. Solicitações sobre os dados podem ser abertas no suporte."}' AS JSON), 'https://cineastra.com.br/privacy', 900001);
INSERT INTO `conteudos_publicados` (`id_conteudo`, `slug`, `versao`, `titulo`, `corpo`, `fonte`, `id_publicador`) VALUES (900009, 'faq', '2.0-cineastra', 'Perguntas frequentes', CAST('{"items":[{"question":"Onde encontro meus ingressos?","answer":"Acesse sua conta e consulte seus pedidos após a aprovação do pagamento."},{"question":"Como faço para acessar o streaming?","answer":"Entre com sua conta, selecione um perfil e escolha um título disponível no seu plano ou adquirido individualmente."}]}' AS JSON), 'https://cineastra.com.br/faq', 900001);
