-- CineAstra · Dados de operação
-- Requer o schema instalado por database/cineastra-install.sql.
-- Executar uma única vez, sem --force. Chaves estrangeiras permanecem ativas.
SET NAMES utf8mb4;
SET SESSION time_zone = '+00:00';
START TRANSACTION;
SET @data_base = UTC_DATE();
SET @competencia = STR_TO_DATE(DATE_FORMAT(@data_base, '%Y-%m-01'), '%Y-%m-%d');


