-- schema_migrations
-- O histórico de migrations é mantido exclusivamente pelo instalador.
-- Nenhum registro é criado, removido ou alterado nesta tabela.

-- Alinhar os preços das sessões futuras aos custos e parâmetros vigentes.
UPDATE sessoes s
JOIN salas a ON a.id_sala = s.id_sala
JOIN precificacao_parametros p ON p.categoria = 'SESSION'
SET s.preco_inteira = (ROUND((ROUND(s.custo_local_dia * 100 * MOD(TIME_TO_SEC(s.horario_fim) - TIME_TO_SEC(s.horario_inicio) + 86400, 86400) / 86400, 0) + s.custo_exibicao * 100) / LEAST(p.ocupacao_referencia, a.capacidade), 0) + ROUND(ROUND((ROUND(s.custo_local_dia * 100 * MOD(TIME_TO_SEC(s.horario_fim) - TIME_TO_SEC(s.horario_inicio) + 86400, 86400) / 86400, 0) + s.custo_exibicao * 100) / LEAST(p.ocupacao_referencia, a.capacidade), 0) * p.markup_bps / 10000, 0)) / 100
WHERE s.id_sessao BETWEEN 900001 AND 900100;

COMMIT;
